def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    fill_ratio = 1.0 - (remaining / np.maximum(bins, 1e-8))
    score = np.where(fill_ratio <= 0.9, 1.0 + 4.0 * (fill_ratio ** 2), 10.0 - 50.0 * ((fill_ratio - 0.9) ** 2))
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    fill_ratio = 1.0 - (remaining / np.maximum(bins, 1e-8))
    score = np.where(fill_ratio <= 0.85, np.exp(fill_ratio), 8.0 - np.exp(5.0 * (fill_ratio - 0.85)))
    return np.where(remaining < 0, -np.inf, score)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    fill_ratio = 1.0 - (remaining / np.maximum(bins, 1e-8))
    target_ratio = 0.9
    penalty = 2.0 * (fill_ratio - target_ratio) ** 2
    return np.where(remaining < 0, -np.inf, -np.exp(penalty))
